import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import {
  MANA_ORDER,
  QUICK_QUESTIONS,
  buildQuickPlacementResult,
  getAnswersFromIndexes,
  runQuickReadingBiasSimulation,
  runQuickReadingExhaustiveAnalysis,
} from "./quick-reading.js";

const factionData = JSON.parse(
  await readFile(new URL("../../data/factions.json", import.meta.url), "utf8")
);
const factions = factionData.factions;
const factionKeys = new Set(Object.keys(factions));

/**
 * Validates the normalized placement result generated by the quick-reading engine.
 *
 * @param {object} placement Quick-reading placement result.
 */
function assertValidPlacement(placement) {
  assert.equal(placement.source_mode, "quick");
  assert.ok(factionKeys.has(placement.faction), `Unknown faction ${placement.faction}`);
  assert.equal(placement.faction_name, factions[placement.faction].name);
  assert.match(placement.institution_type, /^(guild|college)$/);
  assert.ok(placement.world, "Placement should include world.");
  assert.ok(placement.decree.length > 40, "Placement should include a meaningful decree.");
  assert.ok(placement.confidence >= 0 && placement.confidence <= 1);
  assert.equal(placement.top_matches.length, 3);
  assert.equal(placement.adjacent_matches.length, 2);

  MANA_ORDER.forEach((color) => {
    assert.equal(typeof placement.mana_scores[color], "number", `Missing mana score for ${color}`);
    assert.ok(placement.mana_scores[color] >= 1 && placement.mana_scores[color] <= 10);
  });

  placement.top_matches.forEach((match, index) => {
    assert.ok(factionKeys.has(match.faction), `Unknown top match ${match.faction}`);
    assert.equal(match.rank, index + 1);
    assert.ok(match.confidence > 0);
  });

  placement.adjacent_matches.forEach((match) => {
    assert.ok(factionKeys.has(match.faction), `Unknown adjacent match ${match.faction}`);
    assert.notEqual(match.faction, placement.faction);
  });
}

/**
 * Sums the count entries in a selection-bias summary.
 *
 * @param {object} counts Bias count object keyed by faction.
 * @returns {number} Total count.
 */
function sumCounts(counts) {
  return Object.values(counts).reduce((total, entry) => total + entry.count, 0);
}

assert.equal(QUICK_QUESTIONS.length, 5, "Quick reading should have five questions.");
QUICK_QUESTIONS.forEach((question, index) => {
  assert.equal(question.answers.length, 4, `Question ${index + 1} should have four answers.`);
  question.answers.forEach((answer) => {
    Object.keys(answer.boosts || {}).forEach((boostKey) => {
      assert.ok(
        factionKeys.has(boostKey),
        `Unknown boost key ${boostKey} in question ${index + 1}: ${answer.title}`
      );
    });
  });
});

const sampleAnswers = getAnswersFromIndexes([0, 1, 2, 3, 0]);
assertValidPlacement(buildQuickPlacementResult({ answers: sampleAnswers, factions }));

const simulated = runQuickReadingBiasSimulation({
  factions,
  runs: 100,
  seed: "voxmana-selection-bias-v1",
});

assert.equal(simulated.placements.length, 100);
assert.equal(simulated.summary.total, 100);
assert.equal(simulated.summary.assigned.length, 100);
assert.equal(sumCounts(simulated.summary.counts), 100);
assert.equal(
  simulated.summary.guild_vs_college.guild + simulated.summary.guild_vs_college.college,
  100
);
assert.equal(
  Object.values(simulated.summary.top_match_counts).reduce((total, entry) => total + entry.count, 0),
  300
);
simulated.placements.forEach(assertValidPlacement);

const exhaustive = runQuickReadingExhaustiveAnalysis({ factions });
assert.equal(exhaustive.placements.length, 4 ** QUICK_QUESTIONS.length);
assert.equal(sumCounts(exhaustive.summary.counts), exhaustive.placements.length);
assert.equal(
  Object.values(exhaustive.summary.top_match_counts).reduce((total, entry) => total + entry.count, 0),
  exhaustive.placements.length * 3
);
exhaustive.placements.forEach(assertValidPlacement);

console.log(`PASS quick-reading placement tests: ${simulated.placements.length} seeded runs, ${exhaustive.placements.length} exhaustive combinations`);
